head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====
scwin.target1_onbeforeselect = function (selectedIndex, index) {
    scwin.setReturnValue("=====target1_onbeforeselect=====");
    scwin.setReturnValue("selectedIndex : " + selectedIndex + " / index : " + index);
};

scwin.btn_setSelectedIndex_onclick = function (e) {
    scwin.setReturnValue("[호출] setSelectedIndex(0)");
    $p.getComponentById("target1").setSelectedIndex(0);
    scwin.setReturnValue("[호출 후] getSelectedIndex() : " + $p.getComponentById("target1").getSelectedIndex());
};

scwin.btn_setValue_onclick = function (e) {
    scwin.setReturnValue("[호출] setValue(2)");
    $p.getComponentById("target1").setValue("2");
    scwin.setReturnValue("[호출 후] getSelectedIndex() : " + $p.getComponentById("target1").getSelectedIndex());
};
